// === Tab: mySketch.js ===

import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex/src/p5.flex.min.mjs"
/* [Inlined Multi-Tab] shader.js */

mountFlex(p5)

new p5((p) => {
  const [WIDTH, HEIGHT] = [600, 600]
  const PIXEL_DENSITY = 1
  const CANVAS_SIZE = [WIDTH, HEIGHT]
  const TEXEL_SIZE = [
    1 / (p.width * PIXEL_DENSITY),
    1 / (p.height * PIXEL_DENSITY),
  ]

  let cnv, gfx, theShader
  p.setup = () => {
    cnv = p.createCanvas(WIDTH, HEIGHT)
    p.pixelDensity(PIXEL_DENSITY)

    gfx = p.createGraphics(p.width, p.height, p.WEBGL)
    theShader = p.createShader(vert, frag)

    p.noStroke()
    gfx.noStroke()

    p.flex({ container: { padding: "20px" } })
  }

  p.draw = () => {
    p.background(255)
    gfx.background(0)

    // draw square follow mouse
    p.push()
    p.translate(p.mouseX, p.mouseY)
    p.rectMode(p.CENTER)
    p.rotate(p.frameCount * 0.05)
    p.fill("#FF0000")
    p.square(0, 0, 150)
    p.pop()

    gfx.shader(theShader)
    theShader.setUniform("tex0", cnv)
    theShader.setUniform("canvasSize", CANVAS_SIZE)
    theShader.setUniform("texelSize", TEXEL_SIZE)
    theShader.setUniform("mouse", [p.mouseX / p.width, p.mouseY / p.height])
    theShader.setUniform("time", p.frameCount)
    gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

    p.image(gfx, 0, 0)
  }
})



// === Tab: shader.js ===

// noprotect

const circle = `
  float circle(vec2 uv, vec2 position, float radius) {
    return smoothstep( radius-.005, radius+.005, length(uv-position));
  }
`

const frag = `#version 300 es
  precision mediump float;

  uniform sampler2D tex0;
  uniform vec2 texelSize;
  uniform vec2 canvasSize;
  uniform vec2 mouse;
  uniform float time;

  ${circle}

  in vec2 vTexCoord;
  out vec4 fragColor;
  void main() {
    vec2 uv = vTexCoord;
    vec3 canvas = texture(tex0, uv).rgb;
    canvas *= circle(uv, mouse, .05);
    canvas *= vec3(uv, abs(sin(time*0.01)));
    fragColor = vec4(canvas, 1.);
  }
`

const vert = `#version 300 es

  in vec4 aPosition;
  in vec2 aTexCoord;

  out vec2 vTexCoord;

  void main() {
    vTexCoord = aTexCoord;
    gl_Position = aPosition;
  }
`

